#include QMK_KEYBOARD_H
#define _BASE 0  // Base layer
#define _CODE 1  // Code layer

const uint16_t PROGMEM keymaps[][MATRIX_ROWS][MATRIX_COLS] = {
    [_BASE] = LAYOUT(
      KC_MUTE,                     KC_HOME,
      MO(_CODE), KC_MPRV, KC_MNXT, KC_MPLY,
      C(KC_LEFT), C(KC_UP), C(KC_DOWN), C(KC_RIGHT)
    ),
    [_CODE] = LAYOUT(
      KC_MUTE,                     KC_END,
      _______, UG_NEXT, UG_VALU, UG_TOGG,
      G(S(KC_5)), G(A(KC_ESC)), G(KC_F), QK_BOOT
    )
};

bool encoder_update_user(uint8_t index, bool clockwise) {
    if (index == 0) {
        if (clockwise) {
            tap_code(KC_VOLD);
        } else {
            tap_code(KC_VOLU);
        }
    }
    else if (index == 1) {
        if (clockwise) {
            tap_code(KC_PGUP);
        } else {
            tap_code(KC_PGDN);
        }
    }
    return true;
}
